const clean = (v) => { const s = String(v ?? '').trim(); return s || null; };
const hash = (texto, semilla) => { let h = semilla >>> 0; for (let i = 0; i < texto.length; i++) h = Math.imul(h ^ texto.charCodeAt(i), 16777619); return (h >>> 0).toString(16).padStart(8, '0'); };
const clavesRaw = $('Claves ya vistas hoy').first().json.claves;
const vistas = new Set((Array.isArray(clavesRaw) ? clavesRaw : JSON.parse(String(clavesRaw || '[]'))).map(String));
const maximo = Math.max(1, Math.min(100, Number($('Leer configuración').first().json.maximo_por_corrida) || 20));
const lote = new Set();
const salida = [];
for (const { json: r } of $input.all()) {
  const idViaje = Number(r.IdViaje);
  const historialEventoId = Number(r.HistorialEventoId);
  const fotoUrl = clean(r.FotoUrl);
  if (!fotoUrl || !Number.isSafeInteger(idViaje) || !Number.isSafeInteger(historialEventoId)) continue;
  const huella = `${hash(fotoUrl, 2166136261)}${hash(fotoUrl, 3339675911)}`;
  const claveOrigen = `foto:${idViaje}:${huella}`;
  if (vistas.has(claveOrigen) || lote.has(claveOrigen)) continue;
  lote.add(claveOrigen);
  salida.push({ json: {
    claveOrigen,
    idViaje,
    historialEventoId,
    idMotoboy: r.IdMotoboy == null ? null : Number(r.IdMotoboy),
    driverEvento: clean(r.DriverEvento),
    evidenciaEn: new Date(r.EvidenciaEn).toISOString(),
    fotoUrl,
  } });
  if (salida.length >= maximo) break;
}
return salida;
